export const assessGrantProjectBodyIdeaMax = 5000;

export const assessGrantProjectBodyDirectionMin = 2;
export const assessGrantProjectBodyDirectionMax = 200;

export const assessGrantProjectBodyExpectedResultMin = 2;
export const assessGrantProjectBodyExpectedResultMax = 2000;

