/**
 * Creates a preliminary grant project concept from the supplied idea, direction, expected result, duration, and optional clarification answers. The output is for researcher review.
 * @summary Prepare a preliminary research concept
 */
export const prepareGrantConceptBodyIdeaMin = 2;
export const prepareGrantConceptBodyIdeaMax = 5000;

export const prepareGrantConceptBodyDirectionMin = 2;
export const prepareGrantConceptBodyDirectionMax = 200;

export const prepareGrantConceptBodyExpectedResultMin = 2;
export const prepareGrantConceptBodyExpectedResultMax = 2000;

export const prepareGrantConceptBodyDurationMonthsMin = 3;
export const prepareGrantConceptBodyDurationMonthsMax = 84;

export const prepareGrantConceptBodyClarificationAnswersItemMax = 2000;

export const prepareGrantConceptBodyClarificationAnswersMax = 5;



export const PrepareGrantConceptBody = zod.object({
  "idea": zod.string().min(prepareGrantConceptBodyIdeaMin).max(prepareGrantConceptBodyIdeaMax),
  "direction": zod.string().min(prepareGrantConceptBodyDirectionMin).max(prepareGrantConceptBodyDirectionMax),
  "expectedResult": zod.string().min(prepareGrantConceptBodyExpectedResultMin).max(prepareGrantConceptBodyExpectedResultMax),
  "durationMonths": zod.number().int().min(prepareGrantConceptBodyDurationMonthsMin).max(prepareGrantConceptBodyDurationMonthsMax),
  "clarificationAnswers": zod.array(zod.string().min(1).max(prepareGrantConceptBodyClarificationAnswersItemMax)).max(prepareGrantConceptBodyClarificationAnswersMax).optional()
})

export const PrepareGrantConceptResponse = zod.object({
  "title": zod.string(),
  "scientificProblem": zod.string(),
  "relevance": zod.string(),
  "goal": zod.string(),
  "novelty": zod.string(),
  "disclaimer": zod.string(),
  "tasks": zod.array(zod.string()),
  "methods": zod.array(zod.string()),
  "expectedScientificResults": zod.array(zod.string()),
  "expectedPracticalResults": zod.array(zod.string()),
  "implementationStages": zod.array(zod.string()),
  "risks": zod.array(zod.string()),
  "preliminaryAssessment": zod.object({
  "strengths": zod.array(zod.string()),
  "justificationQuestions": zod.array(zod.string()),
  "limitations": zod.array(zod.string()),
  "recommendations": zod.array(zod.string())
})
})


/**
 * Returns an AI-generated response to a bounded conversation. The latest message must be from the user; optional project context and response language are accepted.
 * @summary Respond to the research assistant conversation
 */
export const assistScientificResearchBodyMessagesItemContentMax = 4000;

export const assistScientificResearchBodyMessagesMax = 12;

export const assistScientificResearchBodyContextMax = 4000;



export const AssistScientificResearchBody = zod.object({
  "messages": zod.array(zod.object({
  "role": zod.enum(['user', 'assistant']),
  "content": zod.string().min(1).max(assistScientificResearchBodyMessagesItemContentMax)
})).min(1).max(assistScientificResearchBodyMessagesMax),
  "context": zod.string().max(assistScientificResearchBodyContextMax).optional(),
  "language": zod.enum(['ru', 'kk']).optional()
})

export const assistScientificResearchResponseReplyMax = 4000;



export const AssistScientificResearchResponse = zod.object({
  "reply": zod.string().min(1).max(assistScientificResearchResponseReplyMax)
})


